## components/Sidebar.tsx

Implement Import and Export UI.

```tsx
import React, { useState } from 'react';
import { Character, Scene } from '../types';
import { Button } from './common/Button';
import { AddUserIcon, CollectionIcon, SceneIcon, TrashIcon, ImportIcon, ExportIcon } from '../constants';
import { downloadJson, readJsonFile } from '../utils/fileUtils';

interface SidebarProps {
  characters: Character[];
  selectedCharacterIds: string[];
  onCharacterSelect: (id: string) => void;
  onAddCharacterClick: () => void;
  onImportCharacter: (character: Character) => void;
  onDeleteCharacter: (id: string) => void;
  scenes: Scene[];
  onSceneSelect: (scene: Scene) => void;
  onImportScene: (scene: Scene) => void;
  onSceneDelete: (id: string) => void;
}

const CharacterCard: React.FC<{
  character: Character;
  isSelected: boolean;
  onSelect: () => void;
  onDelete: () => void;
}> = ({ character, isSelected, onSelect, onDelete }) => {
  const handleExport = (e: React.MouseEvent) => {
    e.stopPropagation();
    downloadJson(character, `character-${character.name.replace(/\s+/g, '_')}.json`);
  };

  return (
    <div
      onClick={onSelect}
      className={`relative rounded-lg overflow-hidden cursor-pointer border-2 transition-all group ${
        isSelected ? 'border-indigo-500 scale-105' : 'border-transparent hover:border-indigo-600'
      }`}
    >
      <img src={character.imageUrl} alt={character.name} className="w-full h-auto aspect-square object-cover" />
      <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black to-transparent p-2">
        <p className="text-white font-semibold text-sm truncate pr-6">{character.name}</p>
      </div>
      <div className="absolute top-1 right-1 flex flex-col gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
        <button
          onClick={handleExport}
          className="bg-gray-900/80 p-1 rounded-full text-gray-300 hover:text-white"
          title="Export Character"
        >
          <ExportIcon className="w-3.5 h-3.5" />
        </button>
        <button
          onClick={(e) => { e.stopPropagation(); onDelete(); }}
          className="bg-gray-900/80 p-1 rounded-full text-gray-300 hover:text-red-400"
          title="Delete Character"
        >
          <TrashIcon className="w-3.5 h-3.5" />
        </button>
      </div>
    </div>
  );
};

const SceneCard: React.FC<{
  scene: Scene;
  onSelect: () => void;
  onDelete: () => void;
}> = ({ scene, onSelect, onDelete }) => {
  const handleExport = (e: React.MouseEvent) => {
    e.stopPropagation();
    downloadJson(scene, `scene-${scene.name.replace(/\s+/g, '_')}.json`);
  };

  return (
    <div className="bg-gray-700/50 rounded-lg p-3 border border-gray-600 hover:bg-gray-700 transition-colors group relative">
      <div onClick={onSelect} className="cursor-pointer">
        <h4 className="font-semibold text-white text-sm mb-1 pr-6">{scene.name}</h4>
        <p className="text-xs text-gray-400 line-clamp-2 italic">"{scene.prompt}"</p>
        <div className="mt-2 flex items-center gap-2 text-xs text-gray-500">
           <span className="bg-gray-800 px-1.5 py-0.5 rounded">{scene.characterIds.length} chars</span>
           <span>{new Date(scene.createdAt).toLocaleDateString()}</span>
        </div>
      </div>
      <div className="absolute top-2 right-2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
         <button 
            onClick={handleExport}
            className="p-1 text-gray-500 hover:text-white"
            title="Export Scene"
         >
            <ExportIcon className="w-4 h-4" />
         </button>
         <button 
            onClick={(e) => { e.stopPropagation(); onDelete(); }}
            className="p-1 text-gray-500 hover:text-red-400"
            title="Delete Scene"
         >
            <TrashIcon className="w-4 h-4" />
         </button>
      </div>
    </div>
  );
};

export const Sidebar: React.FC<SidebarProps> = ({ 
  characters, 
  selectedCharacterIds, 
  onCharacterSelect, 
  onAddCharacterClick,
  onImportCharacter,
  onDeleteCharacter,
  scenes,
  onSceneSelect,
  onImportScene,
  onSceneDelete
}) => {
  const [activeTab, setActiveTab] = useState<'CHARACTERS' | 'SCENES'>('CHARACTERS');

  const handleImportClick = (type: 'character' | 'scene') => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'application/json';
    input.onchange = async (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (file) {
        try {
          const data = await readJsonFile(file);
          if (type === 'character') {
             // Simple validation
             if (data.id && data.name && data.imageUrl) {
                onImportCharacter(data);
             } else {
                alert("Invalid character file.");
             }
          } else {
             if (data.id && data.name && Array.isArray(data.characterIds)) {
                onImportScene(data);
             } else {
                alert("Invalid scene file.");
             }
          }
        } catch (err) {
          console.error("Failed to parse file", err);
          alert("Failed to read file.");
        }
      }
    };
    input.click();
  };

  return (
    <aside className="w-64 bg-gray-800/50 flex flex-col border-r border-gray-700">
      {/* Tabs */}
      <div className="flex border-b border-gray-700">
        <button
          onClick={() => setActiveTab('CHARACTERS')}
          className={`flex-1 py-3 text-sm font-medium flex items-center justify-center gap-2 transition-colors ${
            activeTab === 'CHARACTERS' ? 'bg-gray-800 text-white border-b-2 border-indigo-500' : 'text-gray-400 hover:text-gray-200'
          }`}
        >
          <CollectionIcon className="w-4 h-4" />
          Library
        </button>
        <button
          onClick={() => setActiveTab('SCENES')}
          className={`flex-1 py-3 text-sm font-medium flex items-center justify-center gap-2 transition-colors ${
            activeTab === 'SCENES' ? 'bg-gray-800 text-white border-b-2 border-indigo-500' : 'text-gray-400 hover:text-gray-200'
          }`}
        >
          <SceneIcon className="w-4 h-4" />
          Scenes
        </button>
      </div>

      <div className="flex-grow overflow-y-auto p-4">
        {activeTab === 'CHARACTERS' ? (
          <>
            <div className="flex gap-2 mb-4">
              <Button onClick={onAddCharacterClick} className="flex-1 text-xs px-2">
                <AddUserIcon className="w-4 h-4" /> New
              </Button>
              <Button onClick={() => handleImportClick('character')} variant="secondary" className="px-3" title="Import Character JSON">
                <ImportIcon className="w-4 h-4" />
              </Button>
            </div>
            {characters.length === 0 ? (
              <div className="text-center text-gray-400 mt-8">
                <p>Your library is empty.</p>
                <p className="text-sm">Create or import a character.</p>
              </div>
            ) : (
              <div className="grid grid-cols-2 gap-3">
                {characters.map(char => (
                  <CharacterCard
                    key={char.id}
                    character={char}
                    isSelected={selectedCharacterIds.includes(char.id)}
                    onSelect={() => onCharacterSelect(char.id)}
                    onDelete={() => onDeleteCharacter(char.id)}
                  />
                ))}
              </div>
            )}
          </>
        ) : (
          <>
             <Button onClick={() => handleImportClick('scene')} variant="secondary" className="w-full mb-4">
               <ImportIcon className="w-4 h-4" /> Import Scene
             </Button>
             {scenes.length === 0 ? (
               <div className="text-center text-gray-400 mt-8">
                 <p>No saved scenes.</p>
                 <p className="text-sm">Save a scene or import one.</p>
               </div>
             ) : (
               <div className="flex flex-col gap-3">
                 {scenes.map(scene => (
                   <SceneCard 
                     key={scene.id} 
                     scene={scene} 
                     onSelect={() => onSceneSelect(scene)}
                     onDelete={() => onSceneDelete(scene.id)}
                   />
                 ))}
               </div>
             )}
          </>
        )}
      </div>
    </aside>
  );
};
```

## App.tsx

Implement Import, Delete logic and pass to Sidebar.

```tsx
import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Character, ToolType, GeneratedContent, Scene, SoundEffect } from './types';
import { Header } from './components/Header';
import { Sidebar } from './components/Sidebar';
import { Canvas } from './components/Canvas';
import { ControlsPanel } from './components/ControlsPanel';
import { CharacterCreatorModal } from './components/CharacterCreatorModal';

function App() {
  const [characters, setCharacters] = useState<Character[]>([]);
  const [scenes, setScenes] = useState<Scene[]>([]);
  const [soundLibrary, setSoundLibrary] = useState<SoundEffect[]>([]);

  const [activeTool, setActiveTool] = useState<ToolType>('SCENE_BUILDER');
  const [selectedCharacterIds, setSelectedCharacterIds] = useState<string[]>([]);
  const [scenePrompt, setScenePrompt] = useState('Two characters having a picnic in a sunny park.');
  const [sceneSoundEffect, setSceneSoundEffect] = useState<SoundEffect | undefined>(undefined);

  const [characterRotations, setCharacterRotations] = useState<Record<string, number>>({});
  const [characterPositions, setCharacterPositions] = useState<Record<string, { x: number; y: number }>>({});

  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [generatedContent, setGeneratedContent] = useState<GeneratedContent | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [isCreatorModalOpen, setIsCreatorModalOpen] = useState(false);

  // Refs for autosave to access current state in interval
  const scenePromptRef = useRef(scenePrompt);
  const selectedCharacterIdsRef = useRef(selectedCharacterIds);
  const characterRotationsRef = useRef(characterRotations);
  const characterPositionsRef = useRef(characterPositions);

  // Sync refs with state
  useEffect(() => {
    scenePromptRef.current = scenePrompt;
  }, [scenePrompt]);

  useEffect(() => {
    selectedCharacterIdsRef.current = selectedCharacterIds;
  }, [selectedCharacterIds]);

  useEffect(() => {
    characterRotationsRef.current = characterRotations;
  }, [characterRotations]);

  useEffect(() => {
    characterPositionsRef.current = characterPositions;
  }, [characterPositions]);


  // Load from LocalStorage
  useEffect(() => {
    try {
      const savedChars = localStorage.getItem('css_characters');
      if (savedChars) {
        setCharacters(JSON.parse(savedChars));
      }
      const savedScenes = localStorage.getItem('css_scenes');
      if (savedScenes) {
        setScenes(JSON.parse(savedScenes));
      }
      const savedSounds = localStorage.getItem('css_sound_library');
      if (savedSounds) {
        setSoundLibrary(JSON.parse(savedSounds));
      }

      // Load autosave
      const autosavedData = localStorage.getItem('css_autosave');
      if (autosavedData) {
        const parsed = JSON.parse(autosavedData);
        if (parsed.prompt) setScenePrompt(parsed.prompt);
        if (parsed.characterIds) setSelectedCharacterIds(parsed.characterIds);
        if (parsed.rotations) setCharacterRotations(parsed.rotations);
        if (parsed.positions) setCharacterPositions(parsed.positions);
      }
    } catch (e) {
      console.error("Failed to load from local storage", e);
    }
  }, []);

  // Autosave interval
  useEffect(() => {
    const interval = setInterval(() => {
      const dataToSave = {
        prompt: scenePromptRef.current,
        characterIds: selectedCharacterIdsRef.current,
        rotations: characterRotationsRef.current,
        positions: characterPositionsRef.current,
        timestamp: Date.now()
      };
      localStorage.setItem('css_autosave', JSON.stringify(dataToSave));
    }, 60000); // 60 seconds

    return () => clearInterval(interval);
  }, []);

  // Save to LocalStorage whenever they change
  useEffect(() => {
    localStorage.setItem('css_characters', JSON.stringify(characters));
  }, [characters]);

  useEffect(() => {
    localStorage.setItem('css_scenes', JSON.stringify(scenes));
  }, [scenes]);

  useEffect(() => {
    localStorage.setItem('css_sound_library', JSON.stringify(soundLibrary));
  }, [soundLibrary]);


  const handleSetLoading = useCallback((loading: boolean, message: string) => {
    setIsLoading(loading);
    setLoadingMessage(message);
  }, []);

  const handleGenerationComplete = useCallback((content: GeneratedContent) => {
    setGeneratedContent(content);
    setError(null);
  }, []);

  const handleCharacterSelect = (id: string) => {
    setSelectedCharacterIds(prev =>
      prev.includes(id) 
        ? prev.filter(charId => charId !== id) 
        : [...prev, id] // Add new selections to the end (top layer)
    );
  };

  const handleCharacterReorder = useCallback((reorderedCharacters: Character[]) => {
    const newIds = reorderedCharacters.map(c => c.id);
    setSelectedCharacterIds(newIds);
  }, []);

  const handleSaveCharacter = (character: Character) => {
    setCharacters(prev => [...prev, character]);
    setIsCreatorModalOpen(false);
  };

  const handleImportCharacter = (character: Character) => {
    // Avoid duplicates by ID
    if (!characters.some(c => c.id === character.id)) {
        setCharacters(prev => [...prev, character]);
    } else {
        // If ID exists, replace or ignore? Let's replace to allow updates, 
        // or we could generate new ID. For import/export, keeping ID is usually better.
        // But to be safe against user mistakes, let's just alert if duplicate?
        // Let's just update the existing one.
        setCharacters(prev => prev.map(c => c.id === character.id ? character : c));
    }
  };

  const handleDeleteCharacter = (id: string) => {
    setCharacters(prev => prev.filter(c => c.id !== id));
    setSelectedCharacterIds(prev => prev.filter(cid => cid !== id));
  };

  const handleSaveScene = (name: string) => {
    const newScene: Scene = {
      id: crypto.randomUUID(),
      name,
      characterIds: selectedCharacterIds,
      prompt: scenePrompt,
      createdAt: Date.now(),
      soundEffect: sceneSoundEffect,
      rotations: characterRotations,
      positions: characterPositions
    };
    setScenes(prev => [newScene, ...prev]);
  };

  const handleLoadScene = (scene: Scene) => {
    setSelectedCharacterIds(scene.characterIds);
    setScenePrompt(scene.prompt);
    setSceneSoundEffect(scene.soundEffect);
    setCharacterRotations(scene.rotations || {});
    setCharacterPositions(scene.positions || {});

    setGeneratedContent(null); 

    setActiveTool('SCENE_BUILDER');
  };

  const handleImportScene = (scene: Scene) => {
    if (!scenes.some(s => s.id === scene.id)) {
        setScenes(prev => [scene, ...prev]);
    } else {
        setScenes(prev => prev.map(s => s.id === scene.id ? scene : s));
    }
  };

  const handleDeleteScene = (id: string) => {
    setScenes(prev => prev.filter(s => s.id !== id));
  };

  // The order of selectedCharacterIds determines the layer order (index 0 is the back).
  // This logic preserves that order when creating the selectedCharacters array.
  const selectedCharacters = selectedCharacterIds
    .map(id => characters.find(c => c.id === id))
    .filter((c): c is Character => c !== undefined);

  return (
    <div className="h-screen w-screen flex flex-col bg-gray-900">
      <Header activeTool={activeTool} setActiveTool={setActiveTool} />
      <div className="flex flex-grow overflow-hidden">
        <Sidebar
          characters={characters}
          selectedCharacterIds={selectedCharacterIds}
          onCharacterSelect={handleCharacterSelect}
          onAddCharacterClick={() => setIsCreatorModalOpen(true)}
          onImportCharacter={handleImportCharacter}
          onDeleteCharacter={handleDeleteCharacter}
          scenes={scenes}
          onSceneSelect={handleLoadScene}
          onImportScene={handleImportScene}
          onSceneDelete={handleDeleteScene}
        />
        <Canvas
          isLoading={isLoading}
          loadingMessage={loadingMessage}
          generatedContent={generatedContent}
          error={error}
          selectedCharacters={selectedCharacters}
          onCharacterReorder={handleCharacterReorder}
          characterRotations={characterRotations}
          onRotationChange={(id, rot) => setCharacterRotations(prev => ({ ...prev, [id]: rot }))}
          characterPositions={characterPositions}
          onPositionChange={(id, pos) => setCharacterPositions(prev => ({ ...prev, [id]: pos }))}
        />
        <ControlsPanel
          activeTool={activeTool}
          selectedCharacters={selectedCharacters}
          setLoading={handleSetLoading}
          setError={setError}
          onGenerationComplete={handleGenerationComplete}
          scenePrompt={scenePrompt}
          setScenePrompt={setScenePrompt}
          onSaveScene={handleSaveScene}
          sceneSoundEffect={sceneSoundEffect}
          setSceneSoundEffect={setSceneSoundEffect}
          soundLibrary={soundLibrary}
          setSoundLibrary={setSoundLibrary}
          characterRotations={characterRotations}
        />
      </div>
      {isCreatorModalOpen && (
        <CharacterCreatorModal 
          onClose={() => setIsCreatorModalOpen(false)}
          onSave={handleSaveCharacter}
        />
      )}
    </div>
  );
}

